        CssPropertyWithConditions.simple(CssProperty.listStyleType(StyleListStyleType.upperRoman)),
        CssPropertyWithConditions.simple(CssProperty.listStylePosition(StyleListStylePosition.inside)),
        CssPropertyWithConditions.simple(CssProperty.stringSet(StringSet(inner: "title \"Chapter\""))),
    ]
}

// CSS: .anim
public func styleAnim() -> [CssPropertyWithConditions] {
    return [
        CssPropertyWithConditions.simple(CssProperty.animation(StyleAnimationVecValue.exact([StyleAnimation(name: "fadeIn", duration: CssDuration(inner: 300, unit: CssDurationUnit.milliseconds), delay: CssDuration(inner: 0, unit: CssDurationUnit.milliseconds), iterations: AnimationIterationCount.count(1), timing: AnimationTiming.easeInOut, clip: true)]))),
        CssPropertyWithConditions.simple(CssProperty.animationIn(StyleAnimationVecValue.exact([StyleAnimation(name: "flyInLeft", duration: CssDuration(inner: 500, unit: CssDurationUnit.milliseconds), delay: CssDuration(inner: 0, unit: CssDurationUnit.milliseconds), iterations: AnimationIterationCount.count(1), timing: AnimationTiming.spring, clip: true)]))),
        CssPropertyWithConditions.simple(CssProperty.animationOut(StyleAnimationVecValue.exact([StyleAnimation(name: "fadeOut", duration: CssDuration(inner: 200, unit: CssDurationUnit.milliseconds), delay: CssDuration(inner: 0, unit: CssDurationUnit.milliseconds), iterations: AnimationIterationCount.count(1), timing: AnimationTiming.linear, clip: true)]))),
    ]
}
